import {nativeMonsterStats,drawMonsterSprite,MonsterPreview} from './runtime.mjs';
const folded=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/đ/g,'d').toLowerCase();
export function mountMonsterLibrary(h){
 const $=id=>document.getElementById(id),box=document.createElement('div');document.querySelector('.stage').append($('touchPad'));box.className='monster-library';box.innerHTML=`<h3>Thư viện quái Night Camp</h3><p id="monsterLibraryInfo" class="hint" role="status">Đang đọc dữ liệu quái gốc…</p><input id="monsterSearch" aria-label="Tìm quái" placeholder="Tìm tên, ID, kiểu hoặc map gốc…"><select id="monsterCategory" aria-label="Loại quái"><option value="all">Tất cả quái</option><option value="normal">Quái thường</option><option value="elite">Quái tinh anh</option><option value="boss">Boss</option></select><div id="monsterLibraryList"></div><div class="row"><button id="prevMonsters">‹ Trước</button><span id="monsterLibraryPage"></span><button id="nextMonsters">Sau ›</button></div><canvas id="monsterModel" width="320" height="240" aria-label="Xem mẫu quái gốc"></canvas><label>Tư thế xem mẫu<select id="monsterPose"><option value="idle">Đứng / nghỉ</option><option value="attack">Tấn công</option></select></label><p id="monsterStats" class="hint"></p><button id="useMonster" class="primary" disabled>Chọn quái này cho điểm sinh</button><button id="embedUsedMonsters">Nhúng dữ liệu quái gốc của các điểm đã đặt</button><p class="hint">Chỉ quái được chọn/đang dùng được lưu cùng map. Mã riêng vẫn dùng được nếu game mới tự có registry. Mẫu đã lưu không tự bị thư viện gốc ghi đè. Chạy thử: di chuyển cơ bản, đánh 3 lần để hạ quái và kiểm tra hồi sinh; không phải toàn bộ AI gốc, không ghi tiền/EXP.</p>`;
 $('monsterTypeId').parentElement.after(box);$('monsterSpawnCheck').nextElementSibling.textContent='Điểm sinh và dữ liệu mẫu quái đi cùng nguyên map bundle. Bật Chạy thử để xem quái đã nhúng; quái chưa có mẫu chỉ giữ ID cho game mới.';
 const bar=document.createElement('div');bar.id='monsterPreviewBar';bar.className='monster-preview';bar.hidden=true;bar.innerHTML='<button id="hitMonster" disabled>⚔ Đánh thử quái gần</button><label><input id="monsterWander" type="checkbox" checked> Di chuyển thử</label><span id="monsterPreviewInfo" role="status"></span>';document.querySelector('.playbar').append(bar);
 let catalog=[],page=0,chosen=null,images=new Map(),request=0,simulator=null,project=null,playing=false,loaded=false,lastInfo='';const on=(id,event,fn)=>$(id).addEventListener(event,h.safe(fn));
 function gallery(){const q=folded($('monsterSearch').value),cat=$('monsterCategory').value,rows=catalog.filter(m=>(cat==='all'||m.category===cat)&&folded([m.id,m.name,m.originalName,m.kind,...m.maps].join(' ')).includes(q));page=Math.max(0,Math.min(page,Math.max(0,Math.ceil(rows.length/16)-1)));$('monsterLibraryList').replaceChildren(...rows.slice(page*16,page*16+16).map(m=>{const b=document.createElement('button'),img=new Image(),label=document.createElement('span');b.dataset.monster=m.id;b.title=m.name+' · '+m.id;b.className=chosen?.id===m.id?'selected':'';img.src=h.assetURL(m.poses.idle.src);img.loading='lazy';img.alt=m.name;label.textContent=m.name;b.append(img,label);b.onclick=h.safe(()=>select(m));return b}));$('monsterLibraryInfo').textContent=`${rows.length} / ${catalog.length} mẫu quái gốc · ảnh, chỉ số cấp 1–99, hệ và dữ liệu hành vi.`;$('monsterLibraryPage').textContent=(page+1)+' / '+Math.max(1,Math.ceil(rows.length/16));$('prevMonsters').disabled=page===0;$('nextMonsters').disabled=(page+1)*16>=rows.length}
 async function select(m){const token=++request;chosen=null;images=new Map();$('useMonster').disabled=true;$('monsterStats').textContent='Đang tải hai tư thế '+m.id+'…';const pairs=await Promise.all(Object.values(m.poses).map(async s=>[s.src,await h.image(s.src)]));if(token!==request)return;chosen=m;images=new Map(pairs);$('useMonster').disabled=false;gallery();drawModel()}
 function drawModel(){const cv=$('monsterModel'),ctx=cv.getContext('2d');ctx.clearRect(0,0,cv.width,cv.height);ctx.fillStyle='#12202c';ctx.fillRect(0,0,cv.width,cv.height);if(!chosen)return;const m=chosen,level=Number($('monsterLevel').value)||1,stats=nativeMonsterStats(m,level),s=m.poses[$('monsterPose').value],scale=Math.min(1.5,260/s.w,180/s.h);drawMonsterSprite(ctx,m,{x:160,y:215,scale,time:0,attack:$('monsterPose').value==='attack'?1:0},images,{labels:false});$('monsterStats').textContent=`${m.name} · ${m.id} · Cấp ${level} · HP ${stats.maxHp} · Công ${stats.atk.join('–')} · Thủ ${stats.def} · Kháng phép ${stats.mdef} · EXP ${stats.exp} (tham khảo gốc) · Hệ ${m.native.element} · Kiểu ${m.kind} · ${m.source}`}
 on('monsterSearch','input',()=>{page=0;gallery()});on('monsterCategory','change',()=>{page=0;gallery()});on('prevMonsters','click',()=>{page--;gallery()});on('nextMonsters','click',()=>{page++;gallery()});on('monsterPose','change',drawModel);on('monsterLevel','change',drawModel);
 on('useMonster','click',()=>{if(chosen){h.spawnEditor.chooseTemplate(chosen);for(const[src,img]of images)h.state.monsterImages.set(src,img)}});
 on('embedUsedMonsters','click',async()=>{h.stop();const before=h.state.project,ids=new Set((before.monsterSpawns||[]).map(s=>s.monsterId)),known=catalog.filter(m=>ids.has(m.id)&&!before.monsterTypes?.[m.id]),missing=[...ids].filter(id=>!catalog.some(m=>m.id===id)&&!before.monsterTypes?.[id]);const pairs=await Promise.all(known.flatMap(m=>Object.values(m.poses)).map(async s=>[s.src,await h.image(s.src)]));if(h.state.project!==before)throw Error('Map đã đổi trong lúc tải; bấm Nhúng lại');h.update(p=>{for(const m of known)(p.monsterTypes||={})[m.id]=structuredClone(m)});for(const[src,img]of pairs)h.state.monsterImages.set(src,img);h.message('Đã nhúng '+known.length+' mẫu gốc. '+(missing.length?'ID cần registry riêng: '+missing.join(', '):'Xuất nguyên map để đưa sang game.'))});
 on('hitMonster','click',()=>{const result=simulator?.attack(h.state.actor);if(result)h.message(result.killed?'Đã hạ quái thử · chờ hồi sinh theo điểm. Không cộng tiền/EXP.':'Đã đánh quái thử · sát thương mô phỏng 1/3 HP.')});
 async function load(){try{const r=await fetch(new URL('./monsters.json',import.meta.url));if(!r.ok)throw Error('Không tải được thư viện quái');catalog=(await r.json()).monsters;loaded=true;gallery()}catch(e){$('monsterLibraryInfo').textContent=e.message;h.message(e.message)}}
 return {load,tick(dt){
  const st=h.state;if(project!==st.project||playing!==st.playing){project=st.project;playing=st.playing;simulator=null;bar.hidden=!playing;if(playing){simulator=new MonsterPreview(project,{walkOptions:h.walkOptions()});lastInfo=''}}
  if(!playing||!simulator)return;simulator.walkOptions=h.walkOptions();simulator.update(dt,st.actor,{wander:$('monsterWander').checked});const target=simulator.target(st.actor);$('hitMonster').disabled=!target||simulator.attackCooldown>0;const counts=simulator.controller.stats(),info=`${counts.alive} quái · ${simulator.kills} hạ thử · ${counts.waiting} chờ hồi${simulator.missing.length?' · Chưa có mẫu: '+simulator.missing.join(', '):''} · Không lưu tiền/EXP`;if(lastInfo!==info){$('monsterPreviewInfo').textContent=info;lastInfo=info}},drawables(){return simulator?.drawables(h.monsterImages())||[]},get ready(){return loaded}};
}
